   if(m.type!=='save')throw Error('Ação desconhecida.');if(!same(m.context))throw Error('A prova, a conta ou o planejamento mudou. Conecte novamente.');if(S().session&&(!m.timerId||S().session.personalBankId!==m.timerId))throw Error('Há um cronômetro ativo no planejamento. Vincule-o ao banco antes de salvar.');if(m.timerId&&S().session?.personalBankId!==m.timerId)throw Error('O cronômetro vinculado mudou ou foi fechado. Reconecte antes de salvar.');if(personalDraft)throw Error('Já existe uma sessão aguardando conferência no ciclo.');
