   const known=personalTopics(),seen=new Set(),groups=m.groups.map(row=>{if(!S().subjects.some(s=>s.id===row.subjectId)||typeof row.topic!=='string'||!row.topic.trim()||row.topic.length>1000)throw Error('Confira a matéria e o tópico de destino.');if(row.topicId&&!known.some(t=>t.id===row.topicId&&t.subjectId===row.subjectId&&t.name===row.topic))throw Error('O tópico de destino mudou. Conecte novamente.');if(row.notebookId&&!S().questionNotebooks.some(b=>b.id===row.notebookId&&b.subjectId===row.subjectId))throw Error('O caderno de destino mudou.');if(![row.correct,row.wrong,row.seconds].every(n=>Number.isInteger(n)&&n>=0&&n<=604800)||row.correct+row.wrong<1||!Array.isArray(row.attemptIds)||row.attemptIds.length!==row.correct+row.wrong||!Array.isArray(row.questionIds)||row.questionIds.length!==row.attemptIds.length)throw Error('Resultados inválidos.');for(const id of row.attemptIds){if(typeof id!=='string'||id.length>100||seen.has(id))throw Error('Identificação de resposta inválida ou repetida.');seen.add(id);}if(row.questionIds.some(id=>typeof id!=='string'||id.length>180))throw Error('Identificação de questão inválida.');return {...row,topic:row.topic.trim()};});
   const previous=S().history.filter(h=>h.externalSource?.provider==='ciclo-questoes');const ids=new Set(previous.flatMap(h=>h.externalSource.attemptIds||[]));const count=groups.reduce((n,r)=>n+r.attemptIds.length,0),already=[...seen].filter(id=>ids.has(id)).length;if(already===count){personalReply(event,{ok:true,data:{message:'Estas respostas já estão salvas no ciclo.'}});return;}if(already)throw Error('Parte destas respostas já foi salva. Atualize o banco e confira a sessão antes de repetir.');
